package com.capstone.fraudcase.persistence.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PostLoad;
import jakarta.persistence.PostPersist;
import jakarta.persistence.Transient;
import org.springframework.data.domain.Persistable;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

/**
 * Base for entities whose ID is generated by the application (UUID string). Implements {@link Persistable}
 * so Spring Data issues a plain INSERT for new rows instead of a select-then-merge.
 */
@MappedSuperclass
public abstract class AssignedIdEntity implements Persistable<String> {

    @Id
    @Column(name = "id", length = 36, nullable = false, updatable = false)
    private String id;

    @Transient
    private boolean isNew;

    protected AssignedIdEntity() {
    }

    protected AssignedIdEntity(boolean generateId) {
        if (generateId) {
            this.id = UUID.randomUUID().toString();
            this.isNew = true;
        }
    }

    /** Current UTC instant truncated to the DATETIME(6) precision MySQL stores. */
    protected static Instant now() {
        return Instant.now().truncatedTo(ChronoUnit.MICROS);
    }

    protected static Instant toDbPrecision(Instant instant) {
        return instant == null ? null : instant.truncatedTo(ChronoUnit.MICROS);
    }

    @Override
    public String getId() {
        return id;
    }

    @Override
    public boolean isNew() {
        return isNew;
    }

    @PostPersist
    @PostLoad
    void markNotNew() {
        this.isNew = false;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        return o != null && getClass() == o.getClass() && id != null && id.equals(((AssignedIdEntity) o).id);
    }

    @Override
    public int hashCode() {
        return Objects.hash(getClass(), id);
    }
}
